#!/bin/bash\n\n# Comprehensive Deployment Monitor\n# Runs every 5 minutes and writes to files for verification\n\nCHECK_NUM=1\nMAX_CHECKS=12  # 12 * 5 minutes = 60 minutes maximum\n\nwhile [ $CHECK_NUM -le $MAX_CHECKS ]; do\n    OUTPUT_FILE=\"check${CHECK_NUM}_report.txt\"\n    TIMESTAMP=$(date \"+%Y-%m-%d %H:%M:%S\")\n    \n    {\n        echo \"================================\"\n        echo \"CHECK #$CHECK_NUM - $TIMESTAMP\"\n        echo \"================================\"\n        echo \"\"\n        \n        # Docker containers\n        echo \"--- DOCKER CONTAINERS ---\"\n        docker ps -a 2>&1 | head -20\n        echo \"\"\n        \n        # Processes\n        echo \"--- PROCESSES ---\"\n        ps aux | grep -i ansible | head -5\n        ps aux | grep -i deploy.sh | head -5\n        echo \"\"\n        \n        # Container logs if they exist\n        echo \"--- CONTAINER LOGS ---\"\n        if docker ps -a 2>/dev/null | grep -q kafka-ecosystem-cdc; then\n            echo \"Kafka logs (last 30 lines):\"\n            docker logs kafka-ecosystem-cdc 2>&1 | tail -30\n        fi\n        echo \"\"\n        \n        if docker ps -a 2>/dev/null | grep -q postgres-cdc; then\n            echo \"PostgreSQL logs (last 30 lines):\"\n            docker logs postgres-cdc 2>&1 | tail -30\n        fi\n        echo \"\"\n        \n        # Port checks\n        echo \"--- PORT STATUS ---\"\n        for port in 8080 8083 5050 5433 2181 29092; do\n            if curl -s http://localhost:$port > /dev/null 2>&1 || timeout 1 bash -c \"</dev/tcp/localhost/$port\" 2>/dev/null; then\n                echo \"Port $port: UP\"\n            else\n                echo \"Port $port: DOWN\"\n            fi\n        done\n        echo \"\"\n        \n        # Network\n        echo \"--- NETWORK ---\"\n        docker network ls 2>&1 | grep cdc || echo \"cdc-network not found\"\n        echo \"\"\n        \n        # Success check\n        echo \"--- SUCCESS CHECK ---\"\n        if docker ps 2>/dev/null | grep -q kafka-ecosystem-cdc && docker ps 2>/dev/null | grep -q postgres-cdc && docker ps 2>/dev/null | grep -q pgadmin4-cdc; then\n            echo \"✅ ALL CONTAINERS RUNNING\"\n        else\n            echo \"⏳ Still starting...\"\n        fi\n        \n    } > \"$OUTPUT_FILE\" 2>&1\n    \n    echo \"Check $CHECK_NUM complete: $TIMESTAMP\" >> monitor_log.txt\n    \n    CHECK_NUM=$((CHECK_NUM + 1))\n    \n    if [ $CHECK_NUM -le $MAX_CHECKS ]; then\n        sleep 300  # 5 minutes\n    fi\ndone\n\necho \"Monitoring complete\" > monitor_final.txt\n"
